def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    ones = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 1]
    six_lines = set()

    for i, (r1, c1) in enumerate(ones):
        for r2, c2 in ones[i + 1:]:
            dr, dc = r2 - r1, c2 - c1
            if dr == 0 or abs(dr) != abs(dc):
                continue

            sr = 1 if dr > 0 else -1
            sc = 1 if dc > 0 else -1
            path = [(r1 + k * sr, c1 + k * sc) for k in range(abs(dr) + 1)]

            for r, c in path[1:-1]:
                if out[r][c] != 6:
                    out[r][c] = 1

            for r, c in path:
                if grid[r][c] == 6:
                    # Extend the six diagonally in the opposite direction.
                    rr, cc = r, c
                    while 0 <= rr - sr < h and 0 <= cc + sc < w:
                        rr -= sr
                        cc += sc
                    while 0 <= rr < h and 0 <= cc < w:
                        six_lines.add((rr, cc))
                        rr += sr
                        cc -= sc

    for r, c in six_lines:
        if out[r][c] != 1:
            out[r][c] = 6
    return out
